import math
import numpy as np

def mc_call(S0, K, r, sigma, T, n, seed):
    """Plain Monte Carlo price of a European call, and its standard error."""
    if n < 2:
        raise ValueError("a standard error needs at least two paths")
    z = np.random.default_rng(seed).standard_normal(n)   # every normal at once
    ST = S0 * np.exp((r - sigma ** 2 / 2) * T + sigma * math.sqrt(T) * z)
    y = math.exp(-r * T) * np.maximum(ST - K, 0.0)        # discounted payoffs
    return float(y.mean()), float(y.std(ddof=1) / math.sqrt(n))

def paths_for_error(s, target):
    """Paths needed for a standard error of at most target."""
    return math.ceil((s / target) ** 2)
